def transform(g):
    h,w=len(g),len(g[0])
    rs=runs(g)
    o=[r[:] for r in g]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v!=0 and (j==0 or r[j-1]==0) and (j==w-1 or r[j+1]==0):
                cand=[run for run in rs if v in run]
                if not cand: continue
                run=cand[0]
                start=j-run.index(v)
                for k,sv in enumerate(run):
                    c=start+k
                    if 0<=c<w: o[i][c]=sv
    return o

